from copy import deepcopy
from fractions import Fraction
from random import Random

import ledger

rng = Random(417)
checks = 2000


def decimal_string(value):
    return f\"{value // 100}.{value % 100:02d}\"


def spaced(name):
    return \" \" + name.upper() + \" \"


def reference_settle(net):
    net = net.copy()
    result = []
    while any(net.values()):
        debtor = min(net, key=lambda name: (net[name], name))
        creditor = min(net, key=lambda name: (-net[name], name))
        cents = min(-net[debtor], net[creditor])
        assert cents > 0
        net[debtor] += cents
        net[creditor] -= cents
        result.append((debtor, creditor, cents))
    return result


for trial in range(checks):
    names = [f\"person{index:02}\" for index in range(rng.randint(1, 20))]
    rng.shuffle(names)
    group = {\"currency\": \"gBp\", \"members\": [spaced(name) for name in names], \"expenses\": []}
    expected = dict.fromkeys(names, 0)
    for index in range(rng.randrange(20)):
        payer = rng.choice(names)
        amount = rng.randint(1, 10**22)
        among = rng.sample(names, rng.randint(1, len(names)))
        split_type = rng.choice([\"equal\", \"exact\", \"percent\"])
        if split_type == \"exact\":
            edges = [0, *sorted(rng.choices(range(100), k=len(among) - 1)), 100]
            edges = [amount * edge // 100 for edge in edges]
            shares = {name: hi - lo for name, lo, hi in zip(among, edges, edges[1:])}
            split = {\"type\": split_type, \"amounts\": {spaced(name): decimal_string(cents) for name, cents in shares.items()}}
        else:
            if split_type == \"equal\":
                split = {\"type\": split_type, \"among\": [spaced(name) for name in among]}
                if rng.choice([True, False]):
                    del split[\"among\"]
                    among = names
                fractions = dict.fromkeys(among, Fraction(amount, len(among)))
            else:
                edges = [0, *sorted(rng.sample(range(1, 10000), len(among) - 1)), 10000]
                weights = {name: hi - lo for name, lo, hi in zip(among, edges, edges[1:])}
                fractions = {name: Fraction(amount * weight, 10000) for name, weight in weights.items()}
                split = {\"type\": split_type, \"percents\": {spaced(name): decimal_string(weight) for name, weight in weights.items()}}
            shares = {name: int(fraction) for name, fraction in fractions.items()}
            for name in sorted(among, key=lambda name: (shares[name] - fractions[name], name))[:amount - sum(shares.values())]:
                shares[name] += 1
        group[\"expenses\"].append({\"id\": str(index), \"payer\": spaced(payer), \"amount\": decimal_string(amount), \"split\": split})
        expected[payer] += amount
        for name, share in shares.items():
            expected[name] -= share
    original = deepcopy(group)
    assert ledger.balances(group) == expected, trial
    assert sum(expected.values()) == 0, trial
    assert ledger.settle(group) == reference_settle(expected), trial
    assert group == original, trial

print(f\"{checks} randomized groups matched independent Fraction-based balances and settlement.\")
